const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Rectangle([74.5, 26.7, 75.5, 27.2], null, false); // Sambhar Salt Lake, India
    const start1 = '2018-03-01';
    const end1 = '2018-05-31';
    const start2 = '2019-03-01';
    const end2 = '2019-05-31';

    // Function to mask clouds using the Sentinel-2 SCL band
    function maskS2clouds(image) {
        const scl = image.select('SCL');
        // Keep water, vegetation, bare soil, snow, unclassified, dark areas
        const mask = scl.eq(6).or(scl.eq(4)).or(scl.eq(5)).or(scl.eq(11)).or(scl.eq(2)).or(scl.eq(7));
        return image.updateMask(mask);
    }

    // Function to calculate MNDWI
    function addMNDWI(image) {
        const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
        return image.addBands(mndwi);
    }

    // Function to get water area for a given year
    async function getWaterArea(year, start, end, geom) {
        let collection = ee.ImageCollection('COPERNICUS/S2_SR')
            .filterBounds(geom)
            .filterDate(start, end);

        if (collection.size().getInfo() === 0) {
            console.log(`No Sentinel-2 images for ${year}. Trying Landsat 8.`);
            collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterBounds(geom)
                .filterDate(start, end)
                .map(image => {
                    const opticalBands = image.select(['SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B6', 'SR_B7'], ['B2', 'B3', 'B4', 'B5', 'B6', 'B7']).multiply(0.0000275).add(-0.2);
                    const qa = image.select('QA_PIXEL');
                    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0); // Not a cloud
                    return opticalBands.updateMask(cloudMask);
                })
                .map(image => image.normalizedDifference(['B3', 'B6']).rename('MNDWI'));
        } else {
             collection = collection.map(maskS2clouds).map(addMNDWI);
        }

        const collectionSize = collection.size().getInfo();
        if (collectionSize === 0) {
            return {
                area: null,
                size: 0,
                validPixels: 0,
                error: 'C1'
            };
        }

        const composite = collection.select('MNDWI').median();
        const waterThreshold = 0;
        const waterImage = composite.gt(waterThreshold);

        const pixelArea = ee.Image.pixelArea();
        const waterAreaImage = waterImage.multiply(pixelArea);

        const stats = waterAreaImage.reduceRegion({
            reducer: ee.Reducer.sum().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geom,
            scale: 1000,
            maxPixels: 1e10
        });

        const area = ee.Number(stats.get('MNDWI_sum')).divide(1e6).getInfo(); // sq km
        const pixelCount = ee.Number(stats.get('MNDWI_count')).getInfo();

        return {
            area: area,
            size: collectionSize,
            validPixels: pixelCount
        };
    }

    // 2. Data Acquisition & Processing
    const data2018 = await getWaterArea(2018, start1, end1, geometry);
    const data2019 = await getWaterArea(2019, start2, end2, geometry);

    // 3. Validation and Final Answer
    if (data2018.error === 'C1' || data2019.error === 'C1') {
        console.log(`2018 Images: ${data2018.size || 0}`);
        console.log(`2019 Images: ${data2019.size || 0}`);
        console.log("Evidence: No images found for at least one period.");
        console.log("C1");
        return;
    }

    console.log(`2018: ${data2018.area ? data2018.area.toFixed(2) : 'N/A'} sq km water extent from ${data2018.size} images.`);
    console.log(`2019: ${data2019.area ? data2019.area.toFixed(2) : 'N/A'} sq km water extent from ${data2019.size} images.`);
    console.log(`Valid Pixels (2018): ${data2018.validPixels}`);
    console.log(`Valid Pixels (2019): ${data2019.validPixels}`);

    if (data2018.validPixels === 0 || data2019.validPixels === 0) {
        console.log("Evidence: No valid pixels remained after cloud masking for a period.");
        console.log("C2");
        return;
    }

    if (data2018.area === null || data2019.area === null) {
        console.log("Evidence: Calculation failed, result is null.");
        console.log("C3");
        return;
    }

    if (data2019.area < data2018.area) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
